-- Sections 0..40 for السيل الجارف
insert into public.constitution_sections (project_id, key, title, description, sort_order) values
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','00','الغرض من الدستور','السيل الجارف نظام معرفة تاريخية وذاكرة تشغيلية موثوقة، يفصل بين المخطط والمقرر والواقع والتفسير والاستنتاج، وسلامة الحقيقة والتاريخ والمصدر والسياق والزمن أهم من كثرة الخصائص.',0),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','01','المبادئ الحاكمة العليا','قواعد غير قابلة للكسر: قاعدة البيانات مصدر الحقيقة، AI ليس مصدر الحقيقة، عدم خلط أنواع المعرفة، التاريخ لا يُمحى، لكل معلومة Provenance، والزمن جزء من الـDomain.',1),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','02','طبيعة المعمارية','Domain قبل UI، الـDomain مستقل عن الواجهة، والنظام مستقل عن Lovable.',2),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','03','طبقات وكيانات النظام','استقلال الكيانات: System, Plan, Practices, Reality, Conversation, AI Analysis. الخطة ليست النظام والممارسات مستقلة عنهما.',3),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','04','نموذج الحقيقة والبيانات','Raw Reality ثم Structured Data ثم AI Analysis؛ لا يُحذف الأصل بعد الاستخراج ولا يحل الاستنتاج محل البيانات.',4),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','05','المحادثة كمصدر أساسي','المحادثة Input مهم: Message → Extraction → Classification → Evidence → Confirmation → Official Record، مع سؤال المستخدم عند الغموض.',5),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','06','Confirmation وOfficial Records','لا تحويل تلقائي للفكرة أو الاقتراح أو التحليل إلى قرار رسمي؛ والفصل بين AI Suggestion وSystem Action.',6),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','07','التاريخ وHistorical Engine','Historical Snapshot وظيفة أساسية من البداية؛ لا يُعاد بناء الماضي من Current State؛ التصحيح التاريخي لا يمحو الأصل.',7),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','08','Append-Only وData Lifecycle','الكيانات ذات القيمة التاريخية Append-Only أو Versioned؛ لا Hard Delete للتاريخ واستخدام حالات مثل archived وsuperseded.',8),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','09','IDs والعلاقات','هوية ثابتة لكل كيان تاريخي؛ العلاقات تاريخية عند الحاجة؛ الـTimeline مجرد View وليس قاعدة البيانات.',9),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','10','Provenance وEvidence','كل Insight مهم قابل للتتبع حتى المصدر الأصلي، مع معرفة البيانات والفترة والأدلة والـModel والـPrompt ومستوى الثقة.',10),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','11','AI Analysis والسببية','لا يقدّم AI الارتباط كسببية مؤكدة، ويُظهر الأدلة والتفسيرات البديلة وحدود الاستنتاج.',11),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','12','لا يوجد Score واحد للحياة','لا اختزال للنظام في رقم شامل؛ القيمة في فهم العلاقات، وأي تقييم رقمي له معنى محدد وسياق واضح.',12),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','13','عدم التنفيذ ليس فشلًا تلقائيًا','التنفيذ الجزئي لا يُسجَّل Failed تلقائيًا؛ النظام يسجل الواقع أولًا ثم يأتي التفسير.',13),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','14','Database Integrity','سلامة البيانات تُفرض من القاعدة: مفاتيح أجنبية وقيود وحالات انتقال صحيحة، ولا ON DELETE CASCADE عشوائي في البيانات التاريخية.',14),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','15','Security','الأمان يفرضه Backend/Database: Authentication, Authorization, RLS, Server-side validation؛ إخفاء زر ليس أمانًا، والأسرار لا تصل للواجهة.',15),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','16','حماية بيانات المستخدم عند استخدام AI','لا تُرسل قاعدة البيانات كلها إلى AI؛ استرجاع السياق المطلوب فقط وعدم إرسال PII إلا عند الحاجة.',16),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','17','AI قابل للاستبدال','فصل الـDomain عن مزود AI عبر Provider Adapter لتغيير المزود أو النموذج دون إعادة بناء.',17),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','18','إدارة Prompts وAI Metadata','الـPrompts لا تُدفن في الواجهة؛ تسجيل Prompt Version وModel ووقت التنفيذ وSource IDs والثقة.',18),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','19','العمليات الحساسة','Idempotency للعمليات المهمة، Transactions للعمليات المركبة، ومعالجة التزامن.',19),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','20','AI Jobs والعمليات الطويلة','العمليات الطويلة لها حالات واضحة (pending/processing/completed/failed/retrying/cancelled) ومعرّف عملية وتتبع محاولات وأخطاء.',20),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','21','Observability','مراقبة من البداية: Error Logging وOperation ID وJob Status ومدة وسبب الفشل، مع منع تسجيل الأسرار وPII.',21),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','22','Audit Trail','كل تغيير رسمي مهم قابل للتدقيق: من، ماذا، متى، على أي كيان، الحالة السابقة والجديدة والسبب.',22),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','23','الأداء وقابلية التوسع','تصميم لسنوات من البيانات: Pagination، Indexes حسب الاستعلامات الفعلية، Dashboard يطلب الملخص فقط، Cache ليس مصدر حقيقة.',23),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','24','Backup وRecovery','وجود Backup لا يكفي؛ يجب تصور واختبار Restore فعليًا عندما تستحق البنية ذلك.',24),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','25','Migrations','كل تغيير Schema مهم عبر Migration قابلة للتتبع، مع تقييم أثره على البيانات القديمة والتاريخ وRLS وإمكانية التراجع.',25),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','26','قاعدة خاصة بـLovable','Inspect → Reuse → Extend → Replace only when necessary؛ لا إعادة بناء لما يعمل، وكل جلسة محددة الهدف.',26),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','27','Constitution قبل كل Task','قبل أي Task: Inspect → Constitution Impact → Implement → Verify → Record Progress، مع قراءة الجزء الضروري فقط.',27),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','28','لا تهدر موارد Lovable في الفحص','الأولوية للتنفيذ لا لإعادة اكتشاف المعروف؛ لا فحص لأجزاء لا علاقة لها بالمهمة.',28),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','29','تسجيل التنفيذ فورًا','تسجيل ما أُنجز أولًا بأول وعدم انتظار نهاية الجلسة؛ سجل التنفيذ يواكب الواقع حتى لو توقفت الجلسة فجأة.',29),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','30','Tasks صغيرة ومستقلة','مهام محددة صغيرة: تنفيذ → تحقق → تسجيل → المهمة التالية؛ لا انتقال تلقائي لمهمة جديدة إلا بخطة معتمدة.',30),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','31','لا تبنِ كل شيء دفعة واحدة','ترتيب المراحل: Domain/DB/Security/History ثم Conversation/Extraction ثم Reality/Relations/Timeline ثم AI Analysis ثم Reports/Snapshot ثم Performance/UX.',31),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','32','لا تجعل Features تسبق الأساس','مقاومة إغراء Charts وAI Agents وNotifications وScores قبل تثبيت الواقع الموثوق والسجل التاريخي والعلاقات والاستخراج والتحليل.',32),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','33','الاختبارات الإلزامية الأساسية','اختبارات: Historical Engine (V1→V2→V3→Rollback)، عزل AI عن الحقيقة، Idempotency، والتصحيح التاريخي.',33),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','34','قواعد خاصة بالواجهة','الواجهة تعرض العلاقات والمصادر وتميز أنواع المعرفة وتعرض حالة الاقتراح وتتيح مراجعة استخراج AI، ولا توحي أن استنتاج AI حقيقة.',34),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','35','الحوار هو نقطة الإدخال الطبيعية','المستخدم يحكي بحرية والنظام يساعده في الاستخراج مع حفظ المصدر وعدم التحويل لحقيقة دون المسار المناسب.',35),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','36','العلاقات أهم من عرض السجلات','عند عرض مشكلة يمكن الوصول لعلاقاتها: Events, Plan, Practices, System Changes, Decisions, Results, Conversations, Insights.',36),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','37','قواعد البيانات ليست Notes App','لا تحويل النظام إلى Notes + Tasks + Chat + AI Summary؛ لكل معلومة معنى Domain ومصدر وعلاقة وزمن عند اللزوم.',37),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','38','الاستقلال بين Current وHistorical','الحالة الحالية أحدث حالة معتمدة فقط، ولا تُستخدم وحدها لتمثيل التاريخ.',38),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','39','القاعدة الذهبية للتصميم','كل معلومة مهمة يجب الإجابة عنها: ما هي، نوعها، مصدرها، وقت حدوثها وتسجيلها، اعتمادها، أدلتها، علاقاتها، نوع معرفتها، وتاريخ تغيرها.',39),
('7dde1b62-c40e-4dd7-8639-ee93cafc24b3','40','العشر قواعد التقنية الحاكمة','خلاصة الدستور في عشر قواعد حاكمة.',40);

-- Rules extracted from the constitution
insert into public.constitution_rules (project_id, section_id, code, rule_text, rationale, severity, status, keywords, version)
select '7dde1b62-c40e-4dd7-8639-ee93cafc24b3', s.id, v.code, v.rule_text, v.rationale, v.severity::public.rule_severity, 'active', v.keywords::text[], 1
from (values
('00','S00-R01','سلامة الحقيقة والتاريخ والمصدر والسياق والزمن أهم من كثرة الخصائص والواجهات.','الهدف بناء ذاكرة تاريخية موثوقة تجيب بعد سنوات عن حالة النظام وخططه وقراراته وأسبابها وأدلتها.','red_line','{حقيقة,تاريخ,مصدر,أولويات}'),
('00','S00-R02','النظام يجب أن يجيب عن: ماذا كان النظام في تاريخ معين، ماذا كانت الخطة والاعتقاد وقتها، ماذا حدث فعليًا، ما القرارات وأسبابها وأدلتها، وماذا استُنتج لاحقًا.','معيار نجاح النظام على المدى الطويل.','red_line','{أسئلة تاريخية,معيار نجاح}'),
('01','S01-R01','Database هي مصدر الحقيقة: Database ← Application/Domain ← AI Analysis ← UI، وليس UI ← AI ← Database.','لا تكون الواجهة أو AI أو الـCache أو Browser State مصدر الحقيقة.','red_line','{مصدر الحقيقة,داتابيز}'),
('01','S01-R02','AI ليس مصدر الحقيقة: يستخرج ويصنف ويربط ويحلل ويقترح، لكن استنتاجه لا يصبح حقيقة إلا عبر: Source/User ← Recorded Information ← Validation/Confirmation ← Official Record.','AI لا يجعل الشيء حقيقة لمجرد أنه استنتجه.','red_line','{AI,حقيقة,اعتماد}'),
('01','S01-R03','لا خلط بين أنواع المعرفة: FACT وUSER_INTERPRETATION وHYPOTHESIS وAI_INSIGHT وDECISION وPROPOSAL، ولا يجوز تحويل نوع إلى نوع تلقائيًا.','مثال: «الإرهاق سبب عدم التنفيذ» تفسير أو فرضية وليس حقيقة تلقائية.','red_line','{أنواع المعرفة,فصل}'),
('01','S01-R04','التاريخ لا يُمحى: عند Rollback من V4 إلى V2 يظل التاريخ V1→V2→V3→V4→Rollback، فالـRollback نفسه حدث تاريخي جديد.','البيانات التاريخية المهمة لا تُكتب فوقها كتابة مدمرة.','red_line','{تاريخ,Rollback,عدم محو}'),
('01','S01-R05','كل معلومة مهمة لها Provenance: مصدرها، من سجلها، متى حدثت، متى سُجلت، من أين استُخرجت، أدلتها، والتحليل الذي اعتمد عليها.','السلسلة: AI Insight ← Evidence ← Event ← Conversation Message ← Original Source.','red_line','{Provenance,مصدر,أدلة}'),
('01','S01-R06','الزمن جزء من الـDomain: التمييز بين occurred_at وrecorded_at وdiscovered_at وconfirmed_at وeffective_from وeffective_until عندما تتطلب طبيعة الكيان ذلك.','وقت حدوث الشيء ≠ وقت تسجيله ≠ وقت اكتشافه ≠ وقت تفسيره.','red_line','{زمن,occurred_at,recorded_at}'),
('02','S02-R01','التصميم: Domain → Data → Application Logic → UI وليس UI → Tables؛ تُحدد الكيانات وحالاتها وعلاقاتها ودورة حياتها وقواعدها التاريخية ومصادرها وصلاحياتها أولًا ثم تُبنى الواجهات.','لا تُنشأ الجداول لمجرد أن شاشة تحتاجها.','red_line','{Domain أولًا,معمارية}'),
('02','S02-R02','Domain مستقل عن UI: البنية UI ← Application/Services ← Domain ← Database، بحيث يمكن تغيير الواجهة دون إعادة بناء الـDomain.','منع دفن منطق النظام الأساسي داخل Components.','red_line','{استقلال Domain}'),
('02','S02-R03','السيل الجارف مستقل عن Lovable: Lovable أداة تطوير تنفذ النظام ولا تحدد ماهيته، ويجب أن يعمل النظام مستقبلًا عبر GitHub/Vercel/بيئات أخرى دون إعادة اختراع.','قابلية النقل وعدم الارتباط بأداة.','caution','{Lovable,استقلال,قابلية نقل}'),
('03','S03-R01','الحفاظ على استقلال طبقات وكيانات النظام: System, System Version, System Component, System Change, Plan, Plan Policy, Practice, Practice Execution, Practice Evaluation, Reality, Event, Decision, Experiment, Result, Problem, Conversation, Message, Extraction, Evidence, AI Analysis, AI Insight, Pattern.','قد ترتبط الكيانات لكن لا تُدمج في Model واحد لتسهيل التطوير.','red_line','{كيانات,طبقات,استقلال}'),
('03','S03-R02','System ≠ Plan: الخطة مرحلة أو تجربة أو سياسة مؤقتة، ويجب أن نستطيع دراسة هل المشكلة في النظام نفسه أم في طريقة تطبيقه خلال مرحلة.','منع جعل الخطة جزءًا لا ينفصل عن النظام.','red_line','{System,Plan,فصل}'),
('03','S03-R03','Practices مستقلة عن System وPlan: الممارسة قد تتغير أو تتوقف أو يعاد اعتمادها دون أن يتغير النظام بالكامل.','الحفاظ على استقلال الكيانات مع علاقات تاريخية.','caution','{Practices,استقلال}'),
('04','S04-R01','احتفظ بالمصدر الأصلي (Raw Reality) قدر الإمكان: المحادثة الأصلية، الرسالة، الحدث المسجل، المعلومة الخام.','الأصل أساس التحقق وإعادة التحليل.','red_line','{Raw Reality,مصدر أصلي}'),
('04','S04-R02','التحويل إلى بيانات منظمة يتم بعد التحقق، ولا يُحذف الأصل بعد الاستخراج.','Raw Reality ← Structured Facts مع بقاء الأصل.','red_line','{استخراج,عدم حذف}'),
('04','S04-R03','AI Analysis طبقة مشتقة لا تحل محل البيانات التي استُنتجت منها، ويجب إمكانية إعادة التحليل من البيانات الأصلية إذا تغير النموذج أو الـPrompt.','التحليل قابل لإعادة الإنتاج من الأصل.','red_line','{AI Analysis,إعادة تحليل}'),
('05','S05-R01','المحادثة مصدر أساسي: Conversation ← Message ← Extraction ← Classification ← Evidence ← User Confirmation ← Official Record ← Relations ← Analysis مع الاحتفاظ بالمحتوى الأصلي دائمًا.','المحادثة ليست مجرد Chat History بل Input للنظام.','red_line','{محادثة,استخراج,مسار}'),
('05','S05-R02','Extraction كيان مستقل يحتوي: النص الأصلي، نوع المعلومة المقترح، الكيان المقترح، درجة الثقة، مصدر الاستخراج، السياق، وحالة المراجعة (pending/confirmed/edited/rejected).','لا تحويل جملة المستخدم مباشرة إلى حقيقة رسمية.','red_line','{Extraction,مراجعة}'),
('05','S05-R03','AI يسأل عند الغموض ولا يخمن: «وقفتها» تستلزم سؤالًا توضيحيًا لا اختراع معلومة.','الغموض يؤدي إلى سؤال وليس إلى افتراض.','red_line','{غموض,سؤال,لا تخمين}'),
('06','S06-R01','لا تحويل تلقائي للفكرة أو النية أو الاقتراح أو التحليل أو الكلام العابر إلى قرار رسمي؛ التدرج: Idea ← Intent ← Proposal ← Decision ← Approved Change.','«يمكن أغير النظام» لا تعني «تم تغييره».','red_line','{قرار,اعتماد,تدرج}'),
('06','S06-R02','الفصل بين AI Action وAI Analysis: AI Suggestion ← User Review ← Confirmation ← System Action، خصوصًا في إنشاء Version وتغيير System واعتماد Plan وتعديل قرار والأرشفة وحذف أو تغيير سجل تاريخي.','لا يكون AI ← Direct Official Update.','red_line','{AI Action,تأكيد مستخدم}'),
('07','S07-R01','Historical Snapshot وظيفة أساسية من البداية: القدرة على الإجابة «كيف كانت حالة النظام في تاريخ معين؟» ولا تؤجل إلى مرحلة التقارير.','جزء من المعمارية الأساسية وليس Feature لاحقة.','red_line','{Snapshot,تاريخ}'),
('07','S07-R02','لا يُستخدم Current State لإعادة بناء الماضي؛ الماضي يجب أن يكون محفوظًا بطريقة تسمح بإعادة بنائه.','current_plan/current_version لا تكفي لإعادة بناء حالة قديمة.','red_line','{ماضي,إعادة بناء}'),
('07','S07-R03','التصحيح التاريخي لا يمحو الأصل: Original Record ← Correction ← Reason ← Correction Date، ولا يُعدَّل الماضي وكأن التصحيح كان موجودًا وقتها.','لنعرف ماذا كان النظام يعرف في ذلك الوقت.','red_line','{تصحيح تاريخي}'),
('08','S08-R01','الكيانات ذات القيمة التاريخية Append-Only أو Versioned History قدر الإمكان: System Changes, Decisions, Events, Experiments, Results, AI Extractions, Historical Records.','حفظ التاريخ شرط للثقة.','red_line','{Append-Only,Versioned}'),
('08','S08-R02','لا Hard Delete للتاريخ: Not Current ≠ Deleted؛ تُستخدم حالات active/archived/superseded/rejected/withdrawn بحسب طبيعة الكيان، ولا تحويل عشوائي لكل الجداول إلى deleted = true.','إدارة دورة الحياة دون فقد التاريخ.','red_line','{لا حذف,حالات}'),
('09','S09-R01','كل كيان تاريخي مهم يحصل على ID ثابت غير قابل لإعادة الاستخدام؛ تغيير الاسم أو الحالة أو الإصدار أو الارتباطات لا يغير هوية الكيان.','ثبات الهوية أساس التتبع التاريخي.','red_line','{ID,هوية}'),
('09','S09-R02','العلاقات تاريخية عند الحاجة: يجب معرفة أن مشكلة كانت مرتبطة بخطة خلال فترة معينة، لا فقط بالخطة الحالية.','العلاقات نفسها لها بُعد زمني.','caution','{علاقات تاريخية}'),
('09','S09-R03','الـTimeline واجهة عرض/View تجمع من كيانات متعددة (System Changes, Plan Changes, Events, Decisions, Executions, Experiments, Problems, Results) والكيانات الأصلية تظل مستقلة.','لا تجعل Timeline قاعدة البيانات.','caution','{Timeline,View}'),
('10','S10-R01','كل Insight مهم قابل للتتبع: Insight ← AI Analysis ← Evidence ← Events/Decisions/Results ← Conversation Messages ← Original Source، مع تسجيل البيانات المستخدمة والفترة والأدلة والمحادثات والـModel والـPrompt Version ووقت التحليل ومستوى الثقة والتفسيرات البديلة عند الحاجة.','الشفافية الكاملة لمصادر الاستنتاج.','red_line','{تتبع,Evidence,Insight}'),
('11','S11-R01','لا يقدّم AI الارتباط كسببية مؤكدة؛ عند عدم كفاية الدليل يستخدم صياغات مثل «هناك احتمال لوجود علاقة» ويُظهر الأدلة والتفسير والتفسيرات البديلة والفترة ومستوى الثقة وحدود الاستنتاج.','منع تضخيم الاستنتاجات.','red_line','{سببية,ارتباط,ثقة}'),
('12','S12-R01','لا يوجد Score واحد للحياة: لا اختزال للنظام في رقم شامل؛ القيمة في فهم العلاقات System←Plan←Practices←Reality←Problems←Patterns←Insights، وأي تقييم رقمي له معنى محدد وسياق واضح.','منع التبسيط المضلل.','caution','{Score,علاقات}'),
('13','S13-R01','عدم التنفيذ أو التنفيذ الجزئي لا يُسجَّل Failed تلقائيًا؛ قد يكون تنفيذًا جزئيًا أو تجربة أو تعديلًا مقصودًا أو قرارًا واعيًا. النظام يسجل الواقع أولًا ثم يأتي التفسير والتحليل.','الواقع قبل الحكم.','red_line','{تنفيذ جزئي,واقع}'),
('14','S14-R01','سلامة البيانات تُفرض من القاعدة لا الواجهة: Foreign Keys وUnique Constraints وCheck Constraints وNot Null وReferential Integrity وValid State Transitions، ولا ON DELETE CASCADE عشوائي خصوصًا في البيانات التاريخية.','لا اعتماد على الواجهة لمنع الأخطاء.','red_line','{سلامة,قيود,قاعدة بيانات}'),
('15','S15-R01','الأمان يفرضه Backend/Database لا الواجهة: Authentication وAuthorization وRLS وServer-side validation وDatabase constraints؛ إخفاء زر Delete ليس Security.','الأمان الحقيقي في الطبقة الخادمية.','red_line','{أمان,RLS,صلاحيات}'),
('15','S15-R02','RLS تضمن أن كل مستخدم/Tenant يصل فقط لما يملك صلاحيته؛ لا اعتماد على WHERE user_id في الـFrontend فقط.','العزل على مستوى قاعدة البيانات.','red_line','{RLS,عزل}'),
('15','S15-R03','الأسرار لا تصل للواجهة: API Keys الحساسة وService Role Keys وPrivate Tokens وAI Provider Secrets تبقى Server-side أو في Secret Management مناسب.','منع تسريب الأسرار.','red_line','{أسرار,مفاتيح}'),
('16','S16-R01','لا تُرسل قاعدة البيانات كلها إلى AI: User Question ← Relevant Context Retrieval ← Required Data Only ← AI، ولا تُرسل PII أو بيانات حساسة إلا عند الحاجة الفعلية.','تقليل التكلفة والتشويش وخطر الاستنتاج الخاطئ وتسريب البيانات.','red_line','{خصوصية,AI,سياق}'),
('17','S17-R01','AI قابل للاستبدال: البنية AI Service ← Provider Adapter ← AI Provider/Model، ولا يُربط Domain Logic بمزود أو نموذج معين.','تغيير المزود أو النموذج دون إعادة بناء الـDomain.','caution','{AI,Adapter,استبدال}'),
('18','S18-R01','الـPrompts المهمة لا تُدفن في UI Components، ويجب معرفة Prompt Version وModel وParameters ووقت التنفيذ وAnalysis Version وSource IDs وConfidence لكل تحليل.','تغيير الـPrompt أو الـModel قد يغير نتائج التحليل.','caution','{Prompt,إصدار,Metadata}'),
('19','S19-R01','العمليات المهمة آمنة من التكرار (Retry, Double Click, Network Failure, AI Retry, Background Job Retry) باستخدام Idempotency Keys وUnique Constraints حيثما يناسب.','منع السجلات المكررة والآثار المزدوجة.','red_line','{Idempotency,تكرار}'),
('19','S19-R02','العمليات المركبة تنجح بالكامل أو لا تترك حالة نصف مكتملة (Transactions)؛ مثال اعتماد Version: إنشاء النسخة + تحديث النسخة الحالية + سجل التغيير + Audit Log كوحدة واحدة.','منع الحالات الجزئية الفاسدة.','red_line','{Transactions,اتمامية}'),
('19','S19-R03','معالجة التزامن: أكثر من Tab، AI في الخلفية، تعديل متزامن، Jobs تلقائية؛ مع منع أو اكتشاف الكتابات المتعارضة.','سلامة البيانات تحت التزامن.','caution','{تزامن,تعارض}'),
('20','S20-R01','العمليات الطويلة لها حالات واضحة: pending/processing/completed/failed/retrying/cancelled، مع Operation ID ووقت البداية والنهاية وعدد المحاولات والخطأ وسبب الفشل، ولا تعتمد على Request واحد مفتوح.','إدارة موثوقة للـJobs.','execution_rule','{Jobs,حالات,تتبع}'),
('21','S21-R01','Observability من البداية: Error Logging وOperation ID وRequest ID عند الحاجة وJob Status وRetry Count وDuration وFailure Reason، مع منع تسجيل API Keys وTokens وSecrets وPII غير الضروري والمحادثات الكاملة بلا حاجة.','قابلية المراقبة مع حماية البيانات.','execution_rule','{مراقبة,Logs}'),
('22','S22-R01','كل تغيير رسمي مهم قابل للتدقيق: من، ماذا، متى، على أي كيان، الحالة السابقة، الحالة الجديدة، السبب عند الحاجة؛ الـAudit Trail يوثق التغييرات ولا يستبدل البيانات التاريخية.','المساءلة والشفافية.','red_line','{Audit,تدقيق}'),
('23','S23-R01','تصميم لسنوات من البيانات: Pagination/Infinite Loading من البداية حسب الحاجة، وDashboard يطلب الملخص المطلوب فقط ولا يحمل كل التاريخ.','النظام قد يصل لآلاف الرسائل والأحداث والـInsights.','recommendation','{أداء,Pagination}'),
('23','S23-R02','Indexes تُبنى بناءً على الاستعلامات الفعلية (user_id, occurred_at, effective_from/until, entity_id, source_id, status, type) ولا تُنشأ عشرات الـIndexes بلا سبب.','توازن الأداء والتكلفة.','recommendation','{Indexes}'),
('23','S23-R03','يمكن استخدام Cache عندما يناسب لكنه ليس مصدر الحقيقة، مع استراتيجية واضحة لتحديثه وإبطاله.','الكاش أداة لا مرجع.','recommendation','{Cache}'),
('24','S24-R01','وجود Backup لا يكفي؛ يجب وجود تصور واختبار Restore فعلي عندما تصبح البنية في مرحلة تستحق ذلك.','الاستعادة غير المختبرة وهم.','caution','{Backup,Restore}'),
('25','S25-R01','كل تغيير Schema مهم عبر Migration قابلة للتتبع وإعادة التطبيق، وقبل أي تغيير يُعرف: لماذا، الجداول المتأثرة، أثره على البيانات القديمة وعلى Historical Engine وعلى RLS، وإمكانية Rollback وأثره على العلاقات القائمة.','لا تعديل يدوي غير قابل للتتبع.','execution_rule','{Migration,Schema}'),
('26','S26-R01','Lovable لا يعيد بناء ما يعمل: Inspect → Reuse → Extend → Replace only when necessary، وكل جلسة تنفيذية محددة الهدف.','حماية ما هو قائم وموارد التطوير.','execution_rule','{Lovable,إعادة استخدام}'),
('27','S27-R01','قبل تنفيذ أي Task: Inspect → Constitution Impact → Implement → Verify → Record Progress، مع قراءة الجزء الضروري من الدستور والسياق المرتبط بالمهمة فقط دون فحص شامل غير متعلق.','ربط التنفيذ بالدستور دون هدر.','execution_rule','{Task,دستور,تحقق}'),
('28','S28-R01','الأولوية لموارد Lovable هي التنفيذ لا إعادة اكتشاف المعروف؛ لا إعادة قراءة أو تحليل أجزاء لا علاقة لها بالمهمة إلا لمنع خطأ فعلي، ولا إعادة بناء لما هو موجود ويعمل.','ترشيد الـCredits.','execution_rule','{موارد,كفاءة}'),
('29','S29-R01','تسجيل ما أُنجز فورًا أولًا بأول (Implement → Verify → Record Progress) وليس انتظار نهاية الجلسة؛ سجل التنفيذ يبقى مواكبًا للواقع حتى لو توقفت الجلسة فجأة.','محدودية الـCredits واحتمال انتهاء الجلسة.','execution_rule','{تسجيل فوري,تقدم}'),
('30','S30-R01','Tasks صغيرة ومستقلة ومحددة: تنفيذ → تحقق → تسجيل → المهمة التالية؛ لا «ابنِ التطبيق كله» ولا انتقال تلقائي لمهمة جديدة إلا كجزء صريح من خطة معتمدة.','التحكم في النطاق والجودة.','execution_rule','{مهام صغيرة,نطاق}'),
('31','S31-R01','الترتيب المعماري للمراحل: (1) Domain+Database+Security+History، (2) Conversation+Extraction+Confirmation، (3) Reality+Relations+Timeline، (4) AI Analysis+Patterns+Problems، (5) Reports+Historical Snapshot، (6) Performance+UX. لا تقديم AI المتقدم أو Features كثيرة على حساب تثبيت طبقة البيانات والتاريخ.','البناء التدريجي على أساس صلب.','execution_rule','{مراحل,ترتيب}'),
('32','S32-R01','مقاومة إغراء بناء Charts وAI Agents وNotifications وAutomations وScores وRecommendations وGamification قبل تثبيت: Reliable Reality ← Historical Record ← Correct Relations ← Conversation Extraction ← Analysis.','لا Features تسبق الأساس.','caution','{أساس أولًا,Features}'),
('33','S33-R01','اختبار Historical Engine إلزامي: V1→V2→V3→Rollback ثم سؤال «ماذا كانت حالة النظام في التاريخ X؟» ويجب عودة النتيجة الصحيحة دون فقد V2 أو V3.','التحقق من سلامة الذاكرة التاريخية.','verification_rule','{اختبار,Historical Engine}'),
('33','S33-R02','اختبار عزل AI إلزامي: معلومة خاطئة اقترحها AI لا تصبح Fact تلقائيًا، وVersion يقترحها AI لا تنشأ دون التأكيد المطلوب.','التحقق من أن AI لا يصنع الحقيقة.','verification_rule','{اختبار,عزل AI}'),
('33','S33-R03','اختبار Idempotency إلزامي: إرسال نفس الرسالة أو العملية مرتين لا ينشئ تلقائيًا سجلين رسميين متطابقين.','التحقق من أمان التكرار.','verification_rule','{اختبار,Idempotency}'),
('33','S33-R04','اختبار التصحيح التاريخي إلزامي: بعد Original Record ← Correction يجب معرفة ما كان مسجلًا سابقًا ومتى تم التصحيح ولماذا وما الحالة الحالية وما كانت الحالة التاريخية.','التحقق من حفظ التصحيح دون محو الأصل.','verification_rule','{اختبار,تصحيح}'),
('34','S34-R01','الواجهة تعرض العلاقات لا مجرد البيانات، وتعرض مصدر المعلومات عند الحاجة، وتميز بين Fact وInterpretation وHypothesis وAI Insight وDecision، وتعرض حالة الاقتراح قبل اعتماده، وتسمح بمراجعة استخراج AI، ولا توحي أن استنتاج AI حقيقة مؤكدة، ولا تجعل Dashboard بديلًا عن النظام التاريخي.','الواجهة مهمة لكنها ليست مركز الحقيقة.','caution','{واجهة,عرض,تمييز}'),
('35','S35-R01','الحوار نقطة الإدخال الطبيعية: المستخدم يقول «النهارده حصل كذا...» والنظام يساعده في استخراج Event/Decision/Problem/Execution/Result/Interpretation/Hypothesis مع حفظ المصدر الأصلي وعدم التحويل لحقيقة رسمية دون المسار المناسب.','بدل إجبار المستخدم على عشرات النماذج.','caution','{حوار,إدخال}'),
('36','S36-R01','عند عرض مشكلة يجب إمكانية الوصول إلى علاقاتها: Events وPlan وPractices وSystem Changes وDecisions وResults وConversations وAI Insights.','قيمة النظام في فهم العلاقات لا عدد السجلات.','caution','{علاقات,عرض}'),
('37','S37-R01','لا تحويل النظام إلى Notes + Tasks + Chat + AI Summary؛ لكل معلومة معنى Domain واضح ومصدر وعلاقة وزمن عندما يلزم.','هذا التحول يهدم الهدف الأساسي.','red_line','{ليس Notes}'),
('38','S38-R01','التمييز دائمًا بين Current State وHistorical State؛ الحالة الحالية مجرد أحدث حالة معتمدة ولا تُستخدم وحدها لتمثيل التاريخ.','الحاضر ليس التاريخ.','red_line','{Current,Historical}'),
('39','S39-R01','القاعدة الذهبية: كل معلومة مهمة يجب الإجابة عنها — ما هي، نوعها، مصدرها، متى حدثت، متى سُجلت، هل اعتُمدت ومن اعتمدها، أدلتها، ارتباطاتها، هل هي حقيقة أم تفسير أم فرضية أم استنتاج، هل تغيرت وما وضعها السابق؛ وإلا فهذا نقص معماري إذا كانت طبيعتها تتطلب ذلك.','معيار اكتمال تصميم المعلومة.','red_line','{قاعدة ذهبية,اكتمال}'),
('40','S40-R01','القاعدة الحاكمة 1: Database هي مصدر الحقيقة.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,داتابيز}'),
('40','S40-R02','القاعدة الحاكمة 2: Domain مستقل عن UI وLovable.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,استقلال}'),
('40','S40-R03','القاعدة الحاكمة 3: System وPlan وPractices وReality وAI Analysis طبقات وكيانات مستقلة.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,طبقات}'),
('40','S40-R04','القاعدة الحاكمة 4: التاريخ لا يُمحى ولا يُكتب فوقه عندما تكون المحافظة التاريخية مطلوبة.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,تاريخ}'),
('40','S40-R05','القاعدة الحاكمة 5: كل معلومة مهمة لها Source وProvenance وسياق زمني مناسب.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,مصدر}'),
('40','S40-R06','القاعدة الحاكمة 6: AI يحلل ويقترح ويستخرج ولا يصنع الحقيقة تلقائيًا.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,AI}'),
('40','S40-R07','القاعدة الحاكمة 7: كل تغيير رسمي قابل للتتبع والتدقيق.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,تدقيق}'),
('40','S40-R08','القاعدة الحاكمة 8: Security وData Integrity يفرضان من Backend/Database وليس من Frontend.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,أمان}'),
('40','S40-R09','القاعدة الحاكمة 9: العمليات الحساسة آمنة من التكرار والفشل الجزئي والتعارض.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,عمليات}'),
('40','S40-R10','القاعدة الحاكمة 10: Historical Snapshot جزء من المعمارية الأساسية وليس Feature لاحقة.','من العشر قواعد التقنية الحاكمة.','red_line','{حاكمة,Snapshot}'),
('40','S40-R11','الخلاصة النهائية: السيل الجارف يسجل الواقع أولًا، يحفظ تاريخه، يحفظ مصدره وسياقه، ثم يسمح بالتحليل فوقه؛ ولا يسمح للتحليل بأن يعيد كتابة الواقع.','القاعدة التي تحكم كل البنية الفكرية للنظام.','red_line','{خلاصة,واقع أولًا}')
) as v(sec_key, code, rule_text, rationale, severity, keywords)
join public.constitution_sections s on s.project_id = '7dde1b62-c40e-4dd7-8639-ee93cafc24b3' and s.key = v.sec_key;